from contextlib import asynccontextmanager
from uuid import UUID, uuid4

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

from app.broker import broker
from app.db import pool
from app.tasks import process_ai_job


@asynccontextmanager
async def lifespan(app: FastAPI):
    await pool.open(wait=True)
    try:
        await broker.startup()
        try:
            yield
        finally:
            await broker.shutdown()
    finally:
        await pool.close()


app = FastAPI(title="Backend Bootcamp", lifespan=lifespan)


class JobRequest(BaseModel):
    prompt: str = Field(min_length=1, max_length=2000)


class JobAccepted(BaseModel):
    job_id: UUID
    status: str = "queued"


@app.get("/health")
async def health() -> dict[str, str]:
    # Liveness: the process can serve HTTP. No external dependency checks.
    return {"status": "ok"}


@app.get("/ready")
async def ready() -> dict[str, str]:
    async with pool.connection() as conn:
        await conn.execute("SELECT 1")
    return {"status": "ready"}


@app.post("/enqueue", status_code=202, response_model=JobAccepted)
async def enqueue(payload: JobRequest) -> JobAccepted:
    job_id = uuid4()
    try:
        await process_ai_job.kiq(str(job_id), payload.prompt)
    except Exception as exc:
        raise HTTPException(503, "Queue unavailable; try again later") from exc
    return JobAccepted(job_id=job_id)


@app.get("/jobs")
async def list_jobs():
    async with pool.connection() as conn:
        cursor = await conn.execute(
            "SELECT job_id, prompt, word_count, created_at "
            "FROM job_logs ORDER BY created_at DESC LIMIT 20"
        )
        return {"jobs": await cursor.fetchall()}
